import sys
from collections import defaultdict

def findString(N, K):
    def dfs(node, visited, ans):
        for i in range(K):
            edge = node + str(i)
            if edge not in visited:
                visited.add(edge)
                dfs(edge[1:], visited, ans)
                ans.append(i)

    ans = []
    start_node = '0' * (N - 1)
    visited = set()
    dfs(start_node, visited, ans)
    return start_node + ''.join(map(str, ans[::-1]))

def main():
    input = sys.stdin.read().split()
    N = int(input[0])
    K = int(input[1])
    result = findString(N, K)
    print(result)

if __name__ == "__main__":
    main()
